import java.util.*;

public class UploadService {
    private final Map<String, UploadSession> sessions = new HashMap<>();
    private final Map<String, String> tokenToVideo = new HashMap<>(); // idempotency
    private final Queue<String> transcodeQueue = new LinkedList<>();

    public UploadSession createSession(String clientToken, long totalBytes, String checksum) {
        // Idempotent create: retry with same token returns same session.
        // Trade-off: store tokens briefly vs risk double videos on retry.
        for (UploadSession s : sessions.values()) {
            if (s.clientToken.equals(clientToken)) return s;
        }
        String id = UUID.randomUUID().toString();
        UploadSession s = new UploadSession(id, clientToken, totalBytes, checksum);
        sessions.put(id, s);
        return s;
    }

    public String signedChunkUrl(String uploadId, long offset, long length) {
        // In production: return pre-signed blob URL valid for minutes.
        // Bytes go straight to blob store, not through this service.
        return "/blob/" + uploadId + "?offset=" + offset + "&len=" + length;
    }

    public synchronized String complete(String uploadId, long bytesReceived, String sha256) {
        UploadSession s = Objects.requireNonNull(sessions.get(uploadId));
        if (tokenToVideo.containsKey(s.clientToken)) {
            return tokenToVideo.get(s.clientToken); // duplicate completion
        }
        if (bytesReceived != s.totalBytes || !sha256.equals(s.checksum)) {
            s.state = "CORRUPT";
            throw new IllegalStateException("incomplete or corrupt upload");
        }
        String videoId = "v_" + UUID.randomUUID().toString().substring(0, 8);
        tokenToVideo.put(s.clientToken, videoId);
        s.state = "COMMITTED";
        transcodeQueue.add(videoId); // async: never transcode inline
        return videoId;
    }

    static class UploadSession {
        String uploadId; String clientToken;
        long totalBytes; String checksum; String state = "OPEN";
        UploadSession(String u, String t, long b, String c) {
            uploadId = u; clientToken = t; totalBytes = b; checksum = c;
        }
    }
}

def pick_rendition(measured_kbps, renditions, hysteresis_kbps=300):
    """Client-side ABR: pick highest rendition safely below measured throughput.
    Trade-off: aggressiveness (quality) vs stability (rebuffering).
    Hysteresis prevents flapping between two bitrates."""
    candidates = [r for r in renditions if r['kbps'] + hysteresis_kbps <= measured_kbps]
    if not candidates:
        return min(renditions, key=lambda r: r['kbps'])
    return max(candidates, key=lambda r: r['kbps'])


def aggregate_views(events, num_shards=64):
    """Stream-side rollup: dedup by (user, video, minute) then shard.
    Trade-off: exact dedup window costs memory; short window + probabilistic
    filter stops naive view fraud without a DB write per view."""
    seen = set()
    shards = [0] * num_shards
    for e in events:
        key = (e['user_id'], e['video_id'], e['minute'])
        if key in seen:
            continue
        # require minimum watch time before counting
        if e.get('watch_sec', 0) < 5:
            continue
        seen.add(key)
        shard = hash(e['video_id']) % num_shards
        shards[shard] += 1
    return shards
